import{_ as e,o as a,c as d,a2 as o}from"./chunks/framework.mRCPFc5l.js";const b=JSON.parse('{"title":"4. 传送与个人传送点","description":"","frontmatter":{},"headers":[],"relativePath":"teleport.md","filePath":"teleport.md"}'),r={name:"teleport.md"};function s(n,t,c,p,l,h){return a(),d("div",null,[...t[0]||(t[0]=[o(`<h1 id="_4-传送与个人传送点" tabindex="-1">4. 传送与个人传送点 <a class="header-anchor" href="#_4-传送与个人传送点" aria-label="Permalink to &quot;4. 传送与个人传送点&quot;">​</a></h1><h2 id="_4-1-个人传送点" tabindex="-1">4.1 个人传送点 <a class="header-anchor" href="#_4-1-个人传送点" aria-label="Permalink to &quot;4.1 个人传送点&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项目</th><th>规则</th></tr></thead><tbody><tr><td>传送点数量上限</td><td>16 个</td></tr><tr><td>免费传送点</td><td>前 8 个</td></tr><tr><td>第 9 个起</td><td>每个 <strong>8 钻石</strong>（从余额扣）</td></tr><tr><td>公开传送点</td><td>每个 <strong>16 钻石</strong>，最多 5 个</td></tr><tr><td>传送预热</td><td>2 秒；移动或受伤会取消</td></tr><tr><td>传送点名</td><td>最多 16 字符，默认允许中文</td></tr></tbody></table><p>常用命令：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/sethome &lt;名字&gt;          设置传送点</span></span>
<span class="line"><span>/home &lt;名字&gt;             前往传送点</span></span>
<span class="line"><span>/home                    打开传送点列表</span></span>
<span class="line"><span>/delhome &lt;名字&gt;          删除传送点</span></span>
<span class="line"><span>/homelist                列出自己的传送点</span></span>
<span class="line"><span>/homes                   打开传送点 GUI</span></span>
<span class="line"><span>/phome &lt;玩家&gt;.&lt;传送点&gt;   访问别人的公开传送点</span></span></code></pre></div><blockquote><p><code>/home</code> 是个人传送点；<code>/pclaim home</code> 是回自己的领地（优先用 <code>/pclaim settp</code> 设的领地传送点，没设则落领地中心），两者不是同一个系统。</p></blockquote><h2 id="_4-2-主城、公共传送点与回退" tabindex="-1">4.2 主城、公共传送点与回退 <a class="header-anchor" href="#_4-2-主城、公共传送点与回退" aria-label="Permalink to &quot;4.2 主城、公共传送点与回退&quot;">​</a></h2><table tabindex="0"><thead><tr><th>命令</th><th>说明</th></tr></thead><tbody><tr><td><code>/spawn</code></td><td>回主城</td></tr><tr><td><code>/warp court</code></td><td>主城观景台</td></tr><tr><td><code>/warps</code></td><td>列出全部公共传送点</td></tr><tr><td><code>/back</code></td><td>回上一个传送点或死亡点</td></tr></tbody></table><p><code>/warp court</code> 是固定的主城观景台；想随机去主世界开荒请用 <code>/ej</code>。</p><h2 id="_4-3-玩家传送" tabindex="-1">4.3 玩家传送 <a class="header-anchor" href="#_4-3-玩家传送" aria-label="Permalink to &quot;4.3 玩家传送&quot;">​</a></h2><table tabindex="0"><thead><tr><th>命令</th><th>说明</th></tr></thead><tbody><tr><td><code>/tpa &lt;玩家&gt;</code></td><td>请求传送到对方</td></tr><tr><td><code>/tpahere &lt;玩家&gt;</code></td><td>请求对方传送到你</td></tr><tr><td><code>/tpaccept / /tpyes</code></td><td>接受</td></tr><tr><td><code>/tpdeny / /tpno</code></td><td>拒绝</td></tr><tr><td><code>/tpignore</code></td><td>不再接收某人的请求</td></tr></tbody></table><p>传送请求有时效，过期后需要重新发送。</p><h2 id="_4-4-随机传送" tabindex="-1">4.4 随机传送 <a class="header-anchor" href="#_4-4-随机传送" aria-label="Permalink to &quot;4.4 随机传送&quot;">​</a></h2><p>主城提供 <code>/ej</code> 弹射，它就是本服的随机传送：只在主城可用，输入后 5 秒倒计时，把你弹到主世界以 (0,0) 为圆心、半径 1000 格的随机安全落点，并给一次摔落保护（从弹射起算 20 秒，落地即用掉）。它不能指定目的地，也不能在主世界再次使用；想精确去某处请用 <code>/tpa</code> 或自行赶路。</p>`,14)])])}const _=e(r,[["render",s]]);export{b as __pageData,_ as default};
